<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/ol_schema.php';require_once __DIR__.'/../includes/gemini_transport.php';
require_login();require_premium();ensure_ol_schema();if(!in_array(user_grade_number(),[10,11],true))redirect('student/dashboard.php');
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'paper_id',FILTER_VALIDATE_INT);
$p=$id?query_one('SELECT p.*,s.name_en,s.name_si,s.name_ta FROM ol_papers p JOIN subjects s ON s.id=p.subject_id WHERE p.id=? AND p.status=1','i',[$id]):null;if(!$p)redirect('ol-kuppiya/index.php');
$qnum=trim((string)($_GET['q']??$_POST['question_number']??''));$q=$qnum!==''?query_one('SELECT * FROM ol_paper_questions WHERE paper_id=? AND question_number=?','is',[$id,$qnum]):null;
$historyKey='ol_exam_coach_'.(int)$id.'_'.hash('sha256',$qnum);$history=$_SESSION[$historyKey]??[];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'ask');
 if($action==='clear'){$history=[];$_SESSION[$historyKey]=[];redirect('ol-kuppiya/discuss.php?id='.(int)$id.'&q='.rawurlencode($qnum));}
 $message=trim((string)($_POST['message']??''));if($message==='')$error='Write a question or paste your answer first.';
 elseif(GEMINI_API_KEY==='')$error='The O/L Exam Coach is not configured.';
 else{
  $context=$q?(string)$q['question_text']:'No single question was selected.';
  $official=trim((string)($q['answer_text']??''));
  $conversation='';foreach(array_slice($history,-8) as $item)$conversation.=strtoupper((string)$item['role']).': '.(string)$item['text']."\n";
  $instructions="You are K Education O/L Exam Coach, a premium tutor for Sri Lankan GCE O/L students. Subject: {$p['name_en']}. Paper year: {$p['year']}. Student grade: ".user_grade_number().". Medium: ".user()['medium'].". Selected question number: {$qnum}. QUESTION: {$context}. ";
  $instructions.=$official!==''?"OFFICIAL ANSWER OR MARKING CONTEXT: {$official}. ":"No official marking scheme is attached. Never claim that marks or wording are official. ";
  $instructions.="Answer in the student's medium unless asked otherwise. Be accurate, exam-focused and encouraging. If asked for a hint, reveal the method gradually without giving the final answer immediately. If reviewing an answer, identify what is correct, what is missing, and provide an improved model answer. Use clear sections and concise steps. Previous conversation:\n{$conversation}\nSTUDENT: {$message}";
  $payload=json_encode(['contents'=>[['parts'=>[['text'=>$instructions]]]],'generationConfig'=>['temperature'=>0.25,'maxOutputTokens'=>4096]],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
  $response=gemini_http_json(GEMINI_API_BASE.rawurlencode(GEMINI_MODEL).':generateContent?key='.rawurlencode(GEMINI_API_KEY),['Content-Type: application/json'],$payload);
  if($response['status']!==200)$error='The Exam Coach could not answer right now. '.$response['error'];
  else{$body=json_decode($response['body'],true);$answer='';foreach($body['candidates'][0]['content']['parts']??[] as $part)$answer.=(string)($part['text']??'');$answer=trim($answer);if($answer==='')$error='The Exam Coach returned an empty answer. Please retry.';else{$history[]=['role'=>'student','text'=>$message];$history[]=['role'=>'coach','text'=>$answer];$history=array_slice($history,-16);$_SESSION[$historyKey]=$history;}}
 }
}
$pageTitle='O/L Exam Coach';include __DIR__.'/../includes/header.php';
?>
